//! Wire-format regression test.
//!
//! `wire_vectors.txt` is a **frozen snapshot** of the bytes this codec
//! produces. It was originally generated by an independent Python
//! implementation of the format. That implementation is gone: the Rust
//! simulator drives the real routers, so a second implementation of the
//! protocol stopped earning its keep.
//!
//! The snapshot stays, because its value was never really "cross language".
//! It pins the byte layout: move a field by one byte, flip the version, or
//! change a tag length, and this test goes red — instead of silently breaking
//! interoperability with every node already deployed.
//!
//! Each case is rebuilt from its FIELD line, encoded, and compared with the HEX
//! line; the HEX line is then decoded and re-encoded. Both directions of the
//! codec are pinned.
//!
//! **Regenerating**: there is no generator any more. If a format change is
//! intentional, edit the HEX lines by hand or rebuild the file from the new
//! encoder — but read the diff first. That diff *is* the compatibility cost.

use retexis_core::{
    AckBody, Body, ContentType, DataBody, Destination, Envelope, HelloBody, MessageId, NodeId,
    RouteBody,
};
use retexis_crypto::{hmac_sha256, Sealer};
use std::collections::HashMap;

fn from_hex(s: &str) -> Vec<u8> {
    assert!(s.len() % 2 == 0, "odd-length hex: {s}");
    (0..s.len() / 2)
        .map(|i| u8::from_str_radix(&s[i * 2..i * 2 + 2], 16).expect("hex digit"))
        .collect()
}

fn node_id(s: &str) -> NodeId {
    NodeId::from_hex(s).unwrap_or_else(|| panic!("bad node id: {s}"))
}

fn message_id(s: &str) -> MessageId {
    MessageId::from_hex(s).unwrap_or_else(|| panic!("bad message id: {s}"))
}

fn parse_entries(s: &str) -> Vec<(NodeId, u8, String)> {
    if s.is_empty() {
        return Vec::new();
    }
    s.split('|')
        .map(|entry| {
            let mut parts = entry.splitn(3, ':');
            let node = node_id(parts.next().expect("entry id"));
            let metric: u8 = parts
                .next()
                .expect("entry metric")
                .parse()
                .expect("metric is a number");
            let name = parts.next().unwrap_or("").to_string();
            (node, metric, name)
        })
        .collect()
}

fn parse_fields(line: &str) -> HashMap<String, String> {
    line.trim_start_matches("FIELD ")
        .split_whitespace()
        .filter_map(|kv| kv.split_once('='))
        .map(|(k, v)| (k.to_string(), v.to_string()))
        .collect()
}

fn build(f: &HashMap<String, String>) -> Envelope {
    let kind = f.get("kind").expect("kind").as_str();
    let dst = match f.get("dst").map(|s| s.as_str()) {
        Some("-") | None => Destination::Broadcast,
        Some(id) => Destination::Node(node_id(id)),
    };
    let body = match kind {
        "data" => Body::Data(DataBody {
            channel: f.get("channel").cloned().unwrap_or_default(),
            content_type: ContentType::from_u8(
                f.get("ctype")
                    .map(|v| v.parse().expect("ctype"))
                    .unwrap_or(0),
            )
            .expect("known content type"),
            payload: from_hex(f.get("payload").map(|s| s.as_str()).unwrap_or("")),
        }),
        "hello" => Body::Hello(HelloBody {
            name: f.get("name").cloned().unwrap_or_default(),
            link_id: f
                .get("link_id")
                .map(|v| v.parse().expect("link_id"))
                .unwrap_or(0),
        }),
        "route" => Body::Route(RouteBody {
            entries: parse_entries(f.get("entries").map(|s| s.as_str()).unwrap_or("")),
        }),
        "ack" => Body::Ack(AckBody {
            acked: message_id(f.get("acked").expect("acked")),
        }),
        "bye" => Body::Bye,
        other => panic!("unknown kind {other}"),
    };

    Envelope {
        id: message_id(f.get("id").expect("id")),
        src: node_id(f.get("src").expect("src")),
        dst,
        flags: f
            .get("flags")
            .map(|v| v.parse().expect("flags"))
            .unwrap_or(0),
        ttl: f.get("ttl").map(|v| v.parse().expect("ttl")).unwrap_or(8),
        hops: f.get("hops").map(|v| v.parse().expect("hops")).unwrap_or(0),
        created_at_ms: f.get("ts").map(|v| v.parse().expect("ts")).unwrap_or(0),
        body,
    }
}

#[test]
fn the_wire_format_has_not_drifted() {
    let fixture = include_str!("wire_vectors.txt");
    let mut cases = 0usize;
    let mut hmacs = 0usize;
    let mut pending_label: Option<String> = None;
    let mut pending_fields: Option<HashMap<String, String>> = None;

    for (lineno, raw) in fixture.lines().enumerate() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        if let Some(label) = line.strip_prefix("CASE ") {
            pending_label = Some(label.to_string());
        } else if line.starts_with("FIELD ") {
            pending_fields = Some(parse_fields(line));
        } else if let Some(hex) = line.strip_prefix("HEX ") {
            let label = pending_label
                .take()
                .unwrap_or_else(|| panic!("HEX without CASE at line {}", lineno + 1));
            let fields = pending_fields
                .take()
                .unwrap_or_else(|| panic!("HEX without FIELD at line {}", lineno + 1));
            let expected = from_hex(hex);

            let env = build(&fields);
            let encoded = env
                .encode()
                .unwrap_or_else(|e| panic!("{label}: rust refused to encode: {e}"));
            assert_eq!(
                encoded, expected,
                "{label}: the encoder no longer produces the frozen bytes"
            );

            let decoded = Envelope::decode(&expected)
                .unwrap_or_else(|e| panic!("{label}: cannot decode the frozen bytes: {e}"));
            assert_eq!(
                decoded, env,
                "{label}: decoded envelope differs from the fixture fields"
            );
            assert_eq!(
                decoded.encode().unwrap(),
                expected,
                "{label}: re-encode is not stable"
            );
            cases += 1;
        } else if let Some(rest) = line.strip_prefix("HMAC ") {
            let kv = parse_fields(&format!("FIELD {rest}"));
            let key = from_hex(&kv["key"]);
            let msg = from_hex(&kv["msg"]);
            let tag = from_hex(&kv["tag"]);

            let mut full = hmac_sha256(&key, &msg).to_vec();
            full.truncate(tag.len());
            assert_eq!(full, tag, "HMAC mismatch on case {}", kv["label"]);

            let sealed = Sealer::new({
                let mut k = [0u8; 32];
                k.copy_from_slice(&key);
                k
            })
            .seal(&msg);
            assert_eq!(&sealed[msg.len()..], &tag[..], "Sealer tag mismatch");
            hmacs += 1;
        }
    }

    assert!(
        cases >= 10,
        "expected at least 10 envelope cases, got {cases}"
    );
    assert!(hmacs >= 3, "expected at least 3 hmac cases, got {hmacs}");
    println!("verified {cases} envelope cases and {hmacs} hmac cases against the snapshot");
}
